/**
 * Lakeview Labs & Kidney Care: FOLIO export, version 1.
 *
 * Lakeview runs an outreach reference laboratory and a nephrology clinic on one system. The export is a
 * row-for-row copy of that system's tables. Every payload entry is one table row; its `type` is the table
 * name. Column names are the database's own (UPPER_SNAKE). Codes are Lakeview's, documented below; the
 * tables at the end of this file list every code value in use.
 *
 * Two kinds of item, each with its own entry type:
 *
 * - **Lab report items** (`LabReportRow`): one item per requisition, i.e. one set of specimens drawn at
 *   one time for one ordering client. Holds exactly one LAB_REQ row, one LAB_ORDER row per ordered test,
 *   and the LAB_RESULT rows those orders produced. Published when every order on the requisition is
 *   resulted, cancelled or void (rarely earlier, with 'P' rows, when a slow test holds up a requisition
 *   with urgent results). Lab items have no author (system-generated) and no narrative.
 * - **Clinic contact items** (`ClinicRow`): one item per nephrology clinic contact (office visit or
 *   telephone contact). Holds exactly one CLINIC_VISIT row plus the VISIT_DX, VITAL, MED_ORDER and
 *   MED_STATUS_HIST rows entered during that contact. The narrative is the note the nephrologist typed
 *   and signed; it is short and is never generated from the rows.
 *
 * Changes: rows are never edited in place in the export. When a row changes after its item was
 * published (a result invalidated, an order marked entered in error), Lakeview publishes a new item that
 * `supersedes` the old one and restates every row of the requisition or contact with current values.
 * Exception: a medication's status changes are separate MED_STATUS_HIST rows in a later contact, not a
 * re-published MED_ORDER row. See MED_ORDER.MED_STATUS.
 *
 * Times: every timestamp column is RFC 3339 with the UTC offset in effect in America/Chicago at that
 * moment (e.g. `2026-02-09T08:14:00-06:00`). Date-only columns are local calendar dates.
 *
 * Identifiers: REQ_ID, ORDER_ID, RESULT_ID, ACCESSION, VISIT_ID, RX_ID and HIST_ID are Lakeview-assigned,
 * never reused, and unique across the whole export (not only within an item). Rows refer to rows in
 * other items by these ids.
 */

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Lab report items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a lab report item. */
export type LabReportRow = LabReq | LabOrder | LabResult;

/** The requisition: who ordered, when the specimens were drawn. Exactly one per lab report item. */
export interface LabReq {
  type: 'LAB_REQ';

  /** Requisition id, e.g. "RQ-2602090412". */
  REQ_ID: string;

  /**
   * Ordering client account code. Clients are practices that send work to Lakeview.
   * - 'NGFM': Northgate Family Medicine (outside primary care practice).
   * - 'LVNEPH': Lakeview's own nephrology clinic.
   * Other client codes exist for other patients; CLIENT_NAME always carries the display name.
   */
  CLIENT_CODE: string;

  /** Display name of the ordering client, as on the requisition. */
  CLIENT_NAME: string;

  /** NPI of the ordering clinician, 10 digits. Absent when the requisition was standing-order only. */
  ORDERING_NPI?: string;

  /** Ordering clinician's name, "Last, First Credential", as typed on the requisition. */
  ORDERING_NAME?: string;

  /**
   * When the specimens were drawn. This is the clinically meaningful time and the item's `effective`.
   * All specimens on one requisition share it.
   */
  COLLECTED_AT: string;

  /** When the specimens were logged in at the laboratory. */
  RECEIVED_AT: string;

  /**
   * Patient-reported fasting status at draw.
   * - 'Y': fasting at least 8 hours.
   * - 'N': not fasting.
   * - 'U': not asked or not recorded.
   */
  FASTING: 'Y' | 'N' | 'U';
}

/**
 * One ordered test or panel on the requisition. One row per order, even when two orders are run on the
 * same tube (they then share an ACCESSION).
 */
export interface LabOrder {
  type: 'LAB_ORDER';

  /** Order id, e.g. "OR-7730412". */
  ORDER_ID: string;

  /** The LAB_REQ this order belongs to (always the LAB_REQ in the same item). */
  REQ_ID: string;

  /**
   * What was ordered: a Lakeview test code (see `LabTestCode` at the end of this file). An order code
   * may produce several result rows: panel codes (e.g. 'LK-CBC') produce one row per component, and
   * 'LK-CREAT' also produces calculated eGFR rows.
   */
  ORDER_CODE: `${LabTestCode}`;

  /** Display name of the ordered test as printed on the requisition. */
  ORDER_NAME: string;

  /**
   * Specimen container barcode, "LV" + 2-digit year, day of year, 5-digit sequence, e.g. "LV26-040-00093".
   * One accession per tube; several orders can share one. Outside systems that receive Lakeview results
   * (e.g. Northgate) keep this number as their link back to Lakeview.
   */
  ACCESSION: string;

  /**
   * Specimen type.
   * - 'SER': serum.
   * - 'PLA': plasma (lithium heparin).
   * - 'WB': whole blood (EDTA).
   * - 'URN': random urine.
   */
  SPECIMEN_TYPE: 'SER' | 'PLA' | 'WB' | 'URN';

  /**
   * Specimen condition noted on receipt or by the analyzer.
   * - 'OK': acceptable.
   * - 'HEM': hemolyzed. Potassium, AST and LDH can be falsely high. Results are still released, with a
   *   comment; a recollection is usually requested.
   * - 'LIP': lipemic.
   * - 'ICT': icteric.
   * - 'QNS': quantity not sufficient; affected results have RESULT_STATUS 'X'.
   * - 'CLT': clotted.
   */
  SPECIMEN_COND: 'OK' | 'HEM' | 'LIP' | 'ICT' | 'QNS' | 'CLT';

  /**
   * Where the order stands in the lab workflow. Integer code. This is a separate axis from each result
   * row's RESULT_STATUS: an order is 4 (resulted) as soon as its results have been released, and stays 4
   * even if one of its results is later invalidated (RESULT_STATUS 'C'). Never infer result validity from
   * this field.
   * - 1: ordered, not yet collected.
   * - 2: collected, in transit or awaiting testing.
   * - 3: in process (some results may be preliminary).
   * - 4: resulted (results released).
   * - 5: cancelled before testing (no results; see STATUS_REASON).
   * - 9: entered in error (wrong patient, duplicate order). The order is void. Any result rows it has
   *      were produced by the analyzer before the error was caught, still carry their own
   *      RESULT_STATUS (often 'F'), and must not be used.
   */
  ORDER_STATUS: 1 | 2 | 3 | 4 | 5 | 9;

  /** When ORDER_STATUS last changed. */
  STATUS_AT: string;

  /** Free-text reason entered with status 5 or 9, e.g. "Duplicate order". Absent for other statuses. */
  STATUS_REASON?: string;

  /**
   * Set when this order is a repeat draw of an earlier order (in an earlier requisition): that order's
   * ORDER_ID. Absent for ordinary orders.
   */
  REPEAT_OF_ORDER_ID?: string;

  /**
   * Why the repeat draw was taken. Present exactly when REPEAT_OF_ORDER_ID is.
   * - 'HEM': the earlier specimen was hemolyzed. The earlier result is normally invalidated
   *   (RESULT_STATUS 'C', REPLACED_BY_RESULT_ID pointing here).
   * - 'CONF': confirmation of a critical or unexpected value. Both results stand; the earlier one is
   *   NOT invalidated.
   * - 'QNS': the earlier specimen was insufficient.
   */
  REPEAT_REASON?: 'HEM' | 'CONF' | 'QNS';
}

/**
 * One reported result value. Lakeview stores every result as text (VALUE_TEXT) plus a numeric
 * convenience column (VALUE_NUM). VALUE_TEXT is the value of record.
 */
export interface LabResult {
  type: 'LAB_RESULT';

  /** Result id, e.g. "RS-90044817". */
  RESULT_ID: string;

  /** The LAB_ORDER that produced this row (always in the same item). */
  ORDER_ID: string;

  /**
   * Lakeview test code for this result (see `LabTestCode`). Codes are stable across years but are
   * retired and replaced when the method or equation changes: eGFR changed code on 2022-01-10. A
   * mapper that needs a continuous series must join the old and new codes.
   */
  TEST_CODE: `${LabTestCode}`;

  /** Test name as printed on the report on the day it was resulted. Wording varies over the years. */
  TEST_NAME: string;

  /**
   * LOINC code, copied from Lakeview's code table at the moment the row was resulted. Absent when the
   * test code had no LOINC mapping at that moment, which includes some codes that are mapped now (rows
   * resulted before the mapping was added are not back-filled). `LabTestCode` says which codes
   * have a mapping and since when. Do not use LOINC as the only key to find a test; use TEST_CODE.
   */
  LOINC?: string;

  /**
   * The result as reported, as text. Usually a plain decimal ("1.45", "212"). May carry a comparator
   * (">60", "<0.1", ">90") or be non-numeric ("Not done: QNS", "See comment"). Never sort or compare as
   * text.
   */
  VALUE_TEXT: string;

  /**
   * Numeric form of VALUE_TEXT, for queries.
   * - A number when VALUE_TEXT is a plain decimal: the same value.
   * - 9999999 (sentinel) when VALUE_TEXT has a comparator such as ">60": the number is NOT the value;
   *   read VALUE_TEXT.
   * - null when VALUE_TEXT is not numeric.
   */
  VALUE_NUM: number | null;

  /**
   * Unit of VALUE_TEXT, as Lakeview prints it (see `LakeviewUnit`). Fixed per TEST_CODE. Null only when
   * VALUE_TEXT is not numeric. Note 'K/uL' means thousands per microlitre: a platelet count of "212" is
   * 212 000 cells/uL.
   */
  UNIT_CODE: `${LakeviewUnit}` | null;

  /** Reference interval as printed, e.g. "3.5-5.1", "<30", ">59". Text; may be absent for calculated tests. */
  REF_RANGE_TEXT?: string;

  /**
   * Abnormal flag against the reference interval.
   * - 'N': within range.
   * - 'L' / 'H': below / above range.
   * - 'LL' / 'HH': critical low / high (phoned to the ordering clinician).
   * - 'A': abnormal, non-numeric.
   * Absent when the test has no reference interval or the value is not numeric.
   */
  ABN_FLAG?: 'N' | 'L' | 'H' | 'LL' | 'HH' | 'A';

  /**
   * Validity of this row's value. Letter code. Independent of the order's ORDER_STATUS.
   * - 'P': preliminary; a later item will restate the row as 'F'.
   * - 'F': final.
   * - 'A': amended; the value on this row was changed after it was final (for example a transcription
   *   fix). The value shown is the current, valid one; the earlier value is in the superseded item.
   * - 'C': corrected away. The value on this row has been withdrawn and must not be used. If a
   *   replacement exists, REPLACED_BY_RESULT_ID names it (usually in a repeat-draw requisition). Note:
   *   this is NOT the HL7 v2 meaning of 'C' (where 'C' marks the new corrected value); in Lakeview 'C'
   *   marks the old, withdrawn one.
   * - 'X': not performed (cancelled, QNS); VALUE_TEXT says why, VALUE_NUM is null.
   */
  RESULT_STATUS: 'P' | 'F' | 'A' | 'C' | 'X';

  /** When the value was released (first released, for 'A' and 'C' rows). */
  RESULTED_AT: string;

  /** When RESULT_STATUS was set to 'A' or 'C'. Absent otherwise. */
  STATUS_CHANGED_AT?: string;

  /** For RESULT_STATUS 'C': the RESULT_ID of the row that replaces this one. Absent if no replacement. */
  REPLACED_BY_RESULT_ID?: string;

  /**
   * For calculated results: the RESULT_ID of the row it was calculated from (same item): the
   * creatinine row for eGFR, the total cholesterol row for calculated LDL (LK-LDLC).
   * Lakeview calculates eGFR from creatinine, the patient's age and sex on the collection date, and,
   * for the 2009 codes only, a race coefficient (both race variants are always reported; the lab
   * does not know the patient's race).
   */
  DERIVED_FROM_RESULT_ID?: string;

  /** Result comment as printed on the report, free text. Lakeview's comments are canned phrases. */
  COMMENT_TEXT?: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Clinic contact items
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** One row in a nephrology clinic contact item. */
export type ClinicRow = ClinicVisit | VisitDx | Vital | MedOrder | MedStatusHist;

/** The clinic contact itself. Exactly one per clinic contact item. */
export interface ClinicVisit {
  type: 'CLINIC_VISIT';

  /** Contact id, e.g. "NV-104552". */
  VISIT_ID: string;

  /**
   * Kind of contact.
   * - 'NP': new patient office visit.
   * - 'FU': follow-up office visit.
   * - 'TEL': telephone contact (no vitals; CKD_G / CKD_A usually absent).
   */
  VISIT_TYPE: 'NP' | 'FU' | 'TEL';

  /** Start of the contact. The item's `effective`. */
  VISIT_AT: string;

  /** NPI of the nephrologist responsible for the contact. */
  PROVIDER_NPI: string;

  /**
   * KDIGO GFR category as assessed by the nephrologist at this contact: 'G1', 'G2', 'G3a', 'G3b',
   * 'G4', 'G5'. A clinician judgement (usually from two or more eGFRs ≥ 90 days apart), not computed
   * from a single lab value. Absent when not assessed at this contact.
   */
  CKD_G?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';

  /**
   * KDIGO albuminuria category as assessed at this contact: 'A1' (UACR < 30 mg/g), 'A2' (30–300),
   * 'A3' (> 300). Absent when not assessed.
   */
  CKD_A?: 'A1' | 'A2' | 'A3';

  /** Referring practice as typed at registration, free text. Present on 'NP' visits from a referral. */
  REFERRED_BY_TEXT?: string;
}

/** One diagnosis recorded at the contact. The clinic's problem list is the latest VISIT_DX row per code. */
export interface VisitDx {
  type: 'VISIT_DX';

  /** The contact (same item). */
  VISIT_ID: string;

  /** Order of importance at this contact, 1 = primary. */
  DX_RANK: number;

  /** ICD-10-CM code, with the dot (e.g. "N18.32"). Always present. */
  ICD10CM: string;

  /** ICD-10-CM description as shown in the clinic system. */
  DX_TEXT: string;

  /**
   * - 'A': active, confirmed.
   * - 'P': provisional / working diagnosis.
   * - 'R': ruled out at this contact. Not a diagnosis the patient has.
   * - 'H': history of; resolved, recorded for context.
   */
  DX_STATUS: 'A' | 'P' | 'R' | 'H';
}

/**
 * One vital-sign measurement taken at an office visit. Blood pressure is two rows (systolic and
 * diastolic) linked by READING_NO. Unlike lab values, vitals are stored as numbers.
 */
export interface Vital {
  type: 'VITAL';

  /** The contact (same item). */
  VISIT_ID: string;

  /**
   * - 'BPS': systolic blood pressure, mmHg.
   * - 'BPD': diastolic blood pressure, mmHg.
   * - 'HR': heart rate, /min.
   * - 'WT': weight, kg.
   */
  VITAL_CODE: 'BPS' | 'BPD' | 'HR' | 'WT';

  /** The measurement, in UNIT_CODE. */
  VALUE_NUM: number;

  /** 'mmHg' for BPS/BPD, '/min' for HR, 'kg' for WT. Always present. */
  UNIT_CODE: 'mmHg' | '/min' | 'kg';

  /** 1 for the first reading of this VITAL_CODE at the contact, 2 for a repeat, and so on. */
  READING_NO: number;

  /** When the measurement was taken. */
  TAKEN_AT: string;
}

/**
 * A medication prescribed or managed by the nephrology clinic, as the row stood when this item was
 * published. The clinic records only medications it prescribes or changes; it does not keep a full home
 * medication list.
 */
export interface MedOrder {
  type: 'MED_ORDER';

  /** Prescription id, e.g. "RX-30418". Stable for the life of the prescription. */
  RX_ID: string;

  /** The contact at which it was prescribed (same item). */
  VISIT_ID: string;

  /** Lakeview formulary id, e.g. "LVD-04471". Always present; stable across years. */
  LV_DRUG_ID: string;

  /** Drug name and strength from the Lakeview formulary, e.g. "finerenone 10 mg tablet". */
  DRUG_NAME: string;

  /**
   * RxNorm CUI (SCD or SBD) from the formulary. Absent for drugs added to the formulary locally without
   * a mapping; recent additions often have none. Identify the drug by LV_DRUG_ID and DRUG_NAME.
   */
  RXNORM?: string;

  /** Dose per administration, as a number. */
  DOSE_QTY: number;

  /** Unit of DOSE_QTY: 'mg', 'mcg', 'unit', 'mL'. */
  DOSE_UNIT: 'mg' | 'mcg' | 'unit' | 'mL';

  /** 'PO' by mouth, 'SC' subcutaneous, 'IV' intravenous. */
  ROUTE: 'PO' | 'SC' | 'IV';

  /** Frequency code (see `FrequencyCode`). */
  FREQ_CODE: `${FrequencyCode}`;

  /**
   * Status when this row was published. Integer code.
   * - 1: active (patient should be taking it).
   * - 2: discontinued. Final; a restart is a new RX_ID.
   * - 3: on hold. Patient told to stop for now, with intent to resume; not being taken. Can return to 1.
   * - 9: entered in error. The prescription never existed; ignore it.
   *
   * Later changes are NOT made by re-publishing this row. They arrive as MED_STATUS_HIST rows (with the
   * same RX_ID) in later contact items. The current status is NEW_STATUS of the latest MED_STATUS_HIST row
   * for the RX_ID, or this field if there is none.
   */
  MED_STATUS: 1 | 2 | 3 | 9;

  /** Date the patient is to start. Local date. */
  START_DATE: string;

  /** NPI of the prescriber. */
  PRESCRIBER_NPI: string;
}

/** A change to the status of an existing MED_ORDER, made at this contact. */
export interface MedStatusHist {
  type: 'MED_STATUS_HIST';

  /** History row id, e.g. "MH-5520193". */
  HIST_ID: string;

  /** The contact where the change was made (same item). */
  VISIT_ID: string;

  /** The prescription changed. Its MED_ORDER row is in an earlier item. */
  RX_ID: string;

  /** Status before the change (MED_ORDER.MED_STATUS codes). */
  OLD_STATUS: 1 | 2 | 3 | 9;

  /** Status after the change (MED_ORDER.MED_STATUS codes). This is the prescription's current status until a later row. */
  NEW_STATUS: 1 | 2 | 3 | 9;

  /** When the change was made. */
  CHANGED_AT: string;

  /**
   * - 'LAB': abnormal lab result.
   * - 'ADR': adverse drug reaction.
   * - 'PT': patient request.
   * - 'PROC': upcoming procedure.
   * - 'ERR': entered in error.
   * - 'OTH': other; see COMMENT_TEXT.
   */
  REASON_CODE: 'LAB' | 'ADR' | 'PT' | 'PROC' | 'ERR' | 'OTH';

  /** For NEW_STATUS 3: date the clinic plans to review resuming. Local date. Absent otherwise. */
  REVIEW_DATE?: string;

  /** Short free-text comment typed with the change. */
  COMMENT_TEXT?: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────
// Code tables (as of this schema version; a new code means a new schema version)
// ─────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Lakeview lab test codes, used in LAB_ORDER.ORDER_CODE and LAB_RESULT.TEST_CODE. Each member says the
 * specimen, the unit (LAB_RESULT.UNIT_CODE), the LOINC mapping and since when it exists (rows resulted
 * before that date have no LOINC), and the years the code was in use.
 *
 * eGFR reporting rules:
 * - Until 2022-01-09, every LK-CREAT result produced two eGFR rows, LK-EGFR09N and LK-EGFR09A, for
 *   every patient. They are two calculations from the same creatinine, not two measurements; at most
 *   one applies to a given patient, and the lab does not record which.
 * - From 2022-01-10, one row, LK-EGFR21. The old codes were retired; old rows were not recalculated.
 * - Until 2021-06-30, eGFR values of 60 or more were reported as ">60" (VALUE_NUM 9999999). From
 *   2021-07-01, values are reported as numbers up to 90 and as ">90" above.
 */
export declare enum LabTestCode {
  /** Creatinine, serum. Unit mg/dL. LOINC 2160-0 (always). In use 2015–. An LK-CREAT order also produces the calculated eGFR rows. */
  LK_CREAT = 'LK-CREAT',
  /**
   * eGFR, CKD-EPI 2009 equation, non-African American value. Serum. Unit mL/min/1.73m2. In use
   * 2015–2022-01-09. LOINC 48642-3 (always). Note: that LOINC code is defined for the MDRD equation;
   * Lakeview mapped its CKD-EPI 2009 rows to the MDRD codes and never changed the mapping. The
   * equation actually used is the one in COMMENT_TEXT.
   */
  LK_EGFR09N = 'LK-EGFR09N',
  /**
   * eGFR, CKD-EPI 2009 equation, African American value (race coefficient applied). Serum. Unit
   * mL/min/1.73m2. In use 2015–2022-01-09. LOINC 48643-1 (always), which, like LK-EGFR09N's, is an
   * MDRD code; see there.
   */
  LK_EGFR09A = 'LK-EGFR09A',
  /** eGFR, CKD-EPI 2021 equation (no race term). Serum. Unit mL/min/1.73m2. No LOINC mapping. In use 2022-01-10–. */
  LK_EGFR21 = 'LK-EGFR21',
  /** Sodium, serum. Unit mmol/L. LOINC 2951-2 (always). In use 2015–. */
  LK_NA = 'LK-NA',
  /** Potassium, serum. Unit mmol/L. LOINC 2823-3 since 2023-05-01. In use 2015–. */
  LK_K = 'LK-K',
  /** Glucose, serum. Unit mg/dL. LOINC 2345-7 (always). In use 2015–. */
  LK_GLU = 'LK-GLU',
  /** Hemoglobin A1c, whole blood. Unit % (NGSP). LOINC 4548-4 (always). In use 2015–. */
  LK_A1C = 'LK-A1C',
  /** Albumin/creatinine ratio, random urine. Unit mg/g. LOINC 9318-7 since 2023-05-01. In use 2015–. */
  LK_UACR = 'LK-UACR',
  /** CBC without differential, whole blood. Order code only: produces LK-WBC, LK-HGB and LK-PLT result rows. In use 2015–. */
  LK_CBC = 'LK-CBC',
  /** White blood cell count (component of LK-CBC). Unit K/uL. LOINC 6690-2 (always). In use 2015–. */
  LK_WBC = 'LK-WBC',
  /** Hemoglobin (component of LK-CBC). Unit g/dL. LOINC 718-7 (always). In use 2015–. */
  LK_HGB = 'LK-HGB',
  /** Platelet count (component of LK-CBC). Unit K/uL. LOINC 777-3 (always). In use 2015–. */
  LK_PLT = 'LK-PLT',
  /**
   * Lipid panel, serum. Order code only: produces LK-CHOL, LK-TRIG, LK-HDL and LK-LDLC result rows.
   * In use 2015–.
   */
  LK_LIPID = 'LK-LIPID',
  /** Total cholesterol (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2093-3 (always). In use 2015–. */
  LK_CHOL = 'LK-CHOL',
  /** Triglycerides (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2571-8 (always). In use 2015–. */
  LK_TRIG = 'LK-TRIG',
  /** HDL cholesterol (component of LK-LIPID). Serum. Unit mg/dL. LOINC 2085-9 (always). In use 2015–. */
  LK_HDL = 'LK-HDL',
  /**
   * LDL cholesterol, calculated, not measured: total cholesterol − HDL − triglycerides/5 (Friedewald),
   * from the rows of the same panel; DERIVED_FROM_RESULT_ID names the total cholesterol row. Unit
   * mg/dL. LOINC 13457-7 (always). When triglycerides are 400 mg/dL or more the LDL is not calculated:
   * the row then has RESULT_STATUS 'X', VALUE_TEXT "Not calculated: TG >400" and VALUE_NUM null.
   * In use 2015–.
   */
  LK_LDLC = 'LK-LDLC',
}

/** Lakeview unit strings (LAB_RESULT.UNIT_CODE). Each member gives the UCUM equivalent. */
export declare enum LakeviewUnit {
  /** Milligrams per decilitre. UCUM mg/dL. */
  MG_PER_DL = 'mg/dL',
  /** Millimoles per litre. UCUM mmol/L. */
  MMOL_PER_L = 'mmol/L',
  /** Percent; for A1c, NGSP percent. UCUM %. */
  PERCENT = '%',
  /** eGFR, mL/min normalized to 1.73 m² body surface area. UCUM mL/min/{1.73_m2}. */
  ML_MIN_173M2 = 'mL/min/1.73m2',
  /** Milligrams of albumin per gram of creatinine. UCUM mg/g{creat}. */
  MG_PER_G = 'mg/g',
  /** Thousands per microlitre (WBC, platelets): "212" means 212 000 cells/uL. UCUM 10*3/uL. */
  K_PER_UL = 'K/uL',
  /** Grams per decilitre. UCUM g/dL. */
  G_PER_DL = 'g/dL',
}

/** Medication frequency codes (MED_ORDER.FREQ_CODE). */
export declare enum FrequencyCode {
  /** Once daily. */
  QD = 'QD',
  /** Twice daily. */
  BID = 'BID',
  /** Three times daily. */
  TID = 'TID',
  /** Once daily at bedtime. */
  QHS = 'QHS',
  /** Once weekly. */
  QW = 'QW',
  /** As needed. */
  PRN = 'PRN',
}

/**
 * Consumer views: the rows a patient-facing chart application shows for one patient's record at one
 * health organization.
 *
 * Each organization publishes record items ({@link FolioItem}). For each organization a mapper implements
 * {@link Transform}: it receives every item that organization published for one patient (in any order,
 * including superseded and retracted items) and a local date `asOf` (`YYYY-MM-DD`), and returns
 * {@link ViewRows}: the organization's record as it stood at the end of that day. A view the organization has
 * nothing for is an empty array.
 *
 * Rules shared by every view:
 *
 * - **As-of.** An item counts when its `recorded` time is on or before the end of `asOf` (23:59:59.999 local
 *   time). Among those, an item does not count if a counting item supersedes it (directly or through a chain:
 *   if C supersedes B and B supersedes A, A is replaced too) or retracts it. A superseding or retracting item
 *   recorded after `asOf` has no effect yet. `supersedes` and `retracts` only refer to items of the same issuer.
 * - **Corrections versus changes.** Supersession replaces an item entirely (correction, amendment, re-statement).
 *   A retracted item was entered in error and is treated as if it never existed. A change in clinical state (a
 *   medicine paused, a problem resolved) arrives as a new fact in a new item, not as a supersession; the
 *   earlier item still counts as history.
 * - **Time zone.** The consumer's time zone is America/Chicago. "Local date" and "local time" mean wall-clock
 *   time there. Convert date-times that carry an offset or zone to local time (e.g. `2025-03-04T03:30:00Z` is
 *   local date 2025-03-03, 21:30). A date-time with no offset and no zone is already local time: report it as
 *   written, never shift it and never drop it. A plain date is a local date.
 * - **Partial dates.** A source date may be only a year (`2019`) or a year and month (`2019-06`). Keep exactly
 *   the precision the source has; never pad to a full date.
 * - **Only what this organization records.** Report what this organization's items say, without inference from
 *   other organizations and without correcting the source. Rows come from structured payload entries; the
 *   narrative may help interpret an entry, but is never the only basis for a row.
 * - **Evidence.** Every row lists the items (and, where the payload has them, entry ids) it rests on; at least
 *   the item that gives the row its current state.
 * - **Sensitive entries.** Report everything, including entries the organization marks restricted or
 *   confidential. Tag rows with `sensitivity` when the source marks the entry with a sensitive category (map
 *   the source's own category) or when the entry plainly belongs to one (e.g. quetiapine for bipolar disorder →
 *   `mental-health`). Never drop a row because it is sensitive; whether to show or share it is the patient's
 *   later decision.
 * - **Determinism.** Same input, same output. No clock, randomness, network or file access.
 */

/**
 * One record item as published by a health organization. Items are never edited; corrections arrive as new
 * items that supersede or retract earlier ones.
 */
export interface FolioItem {
  /** Record-item format identifier. Carries no clinical meaning. */
  folio: string;

  /** Identifier of this item, unique within the issuer. Referenced by `supersedes`, `retracts` and row evidence. */
  id: string;

  /** The organization that published the item. All items given to one transform call share the same issuer. */
  issuer: string;

  /** The patient the item is about, as identified by the issuer. */
  patient: string;

  /**
   * When the clinical event happened (visit, specimen collection, list review…). Date or date-time, possibly
   * partial. Not used for the as-of cut-off.
   */
  effective: string;
  /** End of the clinical event when it spans a period (e.g. a hospital stay). */
  effective_end?: string;

  /**
   * When the organization committed the item (date-time). Decides whether the item counts for a given `asOf`:
   * it counts when this is on or before the end of `asOf`, local time.
   */
  recorded: string;
  /** Who wrote or signed the item, as far as the issuer says. */
  author?: { id?: string; name?: string; role?: string };

  /**
   * The organization's own schema that types `payload`: its location, the type name within it, and the
   * SHA-256 of the schema document.
   */
  schema?: { url: string; type: string; sha256: string };

  /**
   * Ids of earlier items of the same issuer that this item replaces entirely (correction, amendment,
   * re-statement). Transitive. The replaced items no longer count once this item counts.
   */
  supersedes?: string[];

  /**
   * Ids of earlier items of the same issuer that were entered in error. Nothing replaces them; once this item
   * counts, they are treated as never having existed.
   */
  retracts?: string[];

  /**
   * Human-readable Markdown account of the item. `<ref id="…">` spans point at payload entries. May help
   * interpret an entry; never the only basis for a row.
   */
  narrative: string;

  /** Structured entries, typed by the organization's schema (`schema`). Rows are built from these. */
  payload: Record<string, any>;
}

/**
 * The mapper's entry point. `items`: every item one organization published for one patient, in any order,
 * including superseded and retracted ones. `asOf`: a local date `YYYY-MM-DD`. Returns that organization's
 * record as it stood at the end of `asOf` (America/Chicago). Must be deterministic.
 */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** All rows for one organization, one patient, one as-of date. Each array is empty when there is nothing. */
export interface ViewRows {
  /** Outpatient (home) medicines, one row per drug ingredient. */
  medications: MedicationRow[];
  /** Conditions the patient has or had, one row per condition. */
  problems: ProblemRow[];
  /** Current substances to avoid because of a past reaction. */
  allergies: AllergyIntoleranceRow[];
  /** Laboratory results for the listed analytes, one row per result. */
  labs: LabResultRow[];
  /** Clinic and hospital vital-sign sets and home readings. */
  vitals: VitalRow[];
}

/**
 * A local date with the precision the source has: `YYYY`, `YYYY-MM` or `YYYY-MM-DD`. Never padded
 * (a source saying "June 2019" gives `2019-06`, not `2019-06-01`).
 */
export type PartialDate = string;

/**
 * The items a row rests on. Must include at least the item that gives the row its current state; may
 * include earlier items it also relies on (e.g. the start of a medicine that is now held).
 * `item_id`: the item's `id`. `entry_id`: the id of the payload entry within that item, when it has one.
 */
export type Evidence = { item_id: string; entry_id?: string }[];

/**
 * Sensitive categories. `mental-health`: psychiatric conditions and their treatment (e.g. bipolar disorder,
 * quetiapine). `substance-use`: alcohol, opioid or other substance use disorders and their treatment
 * (e.g. buprenorphine). `sexual-reproductive-health`: contraception, pregnancy, fertility, sexual health.
 * `hiv-sti`: HIV and other sexually transmitted infections and their treatment (e.g. chlamydia, an
 * antiretroviral). `genetic`: genetic test results and inherited conditions (e.g. a BRCA1 variant).
 * Set when the source marks the entry with such a category (map the source's own category) or when the entry
 * plainly belongs to one. Omit when none applies.
 */
export type Sensitivity = 'mental-health' | 'substance-use' | 'sexual-reproductive-health' | 'hiv-sti' | 'genetic';

/**
 * One outpatient (home) medicine. Hospital-only orders (infusions, drugs given only during a stay) are not
 * rows; a discharge prescription for home use is.
 *
 * One row per drug ingredient. If the source has several lines or orders for the same ingredient over time,
 * report the most recent one: the one whose own latest event (start, change, hold, resume, stop) is latest.
 * A line or order entered in error never existed. Stopped medicines that the source still shows are rows.
 *
 * Snapshots versus events: if the source publishes its medication list as repeated snapshots (each item a
 * full list), the latest counting snapshot is the list, and a drug absent from it is not reported. If the
 * source publishes events or status changes per line, the latest event for a line decides its state, however
 * old that event is.
 *
 * If a patient's own list names the same drug twice with conflicting statuses, report one row for it; which
 * entry wins is not specified.
 */
export interface MedicationRow {

  /**
   * Generic ingredient name, lower case, without salt or dosage form; brand names translated
   * (e.g. "Ventolin HFA" → "albuterol", "amoxicillin trihydrate 500 mg capsule" → "amoxicillin").
   * Omit only when the record does not say which drug it is.
   */
  ingredient?: string;

  /**
   * RxNorm code of the ingredient (term type IN), only when the source itself states an ingredient-level
   * code. Never looked up or derived from a product-level code.
   */
  rxnorm_ingredient?: string;

  /** The medicine's name as the source writes it (e.g. "Ventolin HFA 90 mcg/actuation inhaler"). */
  drug_name: string;

  /**
   * - `active`: the patient should be taking it (clinician record) or says they are taking it (own list).
   * - `held`: paused, with intent or possibility of resuming; not taking now. Distinct from stopped.
   *   On a patient's own list, an entry marked as taken but annotated by the patient as paused or stopped
   *   for the time being is held.
   * - `stopped`: discontinued.
   * - `unknown`: listed with no decision recorded (e.g. a list the source marks as not reviewed).
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';

  /**
   * Local date the current status began, per the source: the hold date for held, the stop date for stopped,
   * the start or resume date for active. Source precision. Omit if unknown.
   */
  status_since?: PartialDate;

  /**
   * Amount per administration currently prescribed; for held or stopped rows, the amount at the time of the
   * hold or stop. On a patient's own list, the amount the patient says they take.
   * - Strength per unit and a count: report the mass (strength × count): "famotidine 10 mg, take 2 tablets"
   *   → 20 mg; "albuterol 90 mcg/puff, 2 puffs" → 180 mcg.
   * - No count but a time ("take in the evening") means one unit: "cetirizine 10 mg tablet, take in the
   *   evening" → 10 mg.
   * - `tablet` only when the strength is unknown ("1 tablet of prednisone", strength not given → 1 tablet).
   * - Normalize unit spellings: "milligrams" → mg; "µg", "mcg", "micrograms" → mcg; "U", "IU", "unit(s)" →
   *   units; "ml", "cc" → mL; "tab(s)" → tablet.
   * - Omit when there is no single amount: a range ("1–2 puffs"), a sliding scale, an amount that depends on
   *   a condition, or a strength with no directions at all.
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };

  /**
   * QD once daily; BID twice daily (also "every 12 hours"); TID three times daily (also "every 8 hours");
   * QHS once daily at bedtime; QW once weekly; PRN as needed (e.g. "every 6 hours as needed for wheeze");
   * other for any other schedule (four times daily, every other day, monthly, tapering). A once-daily direction
   * given only as "nightly" or "at night" may be QHS or QD. Omit when the source gives no frequency.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';

  /**
   * Only for stopped rows, and only when the source gives a coded or clearly stated reason.
   * `adverse_reaction`: stopped because of a side effect or reaction (e.g. rash on amoxicillin).
   * `ineffective`: did not work. `therapy_changed`: replaced by another drug or regimen.
   * `course_complete`: a planned course ended (e.g. a 10-day antibiotic course). `patient_choice`: the
   * patient decided to stop. `other`: a stated reason that fits none of these.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';

  /** The source's free-text reason for the current status, as written (e.g. "holding until after knee surgery"). */
  status_reason_text?: string;

  /** true for the patient's own account (a self-reported list); false for a clinician's record. */
  patient_reported: boolean;

  /** true when the source says the medicine was bought without a prescription (over the counter). Omit otherwise. */
  otc?: boolean;

  /** Sensitive categories of this medicine; see {@link Sensitivity}. Omit when none applies. */
  sensitivity?: Sensitivity[];
  /** Items and entries this row rests on; at least the one giving the current status. */
  evidence: Evidence;
}

/**
 * A condition the source asserts the patient has or had. One row per condition: entries that restage or
 * recode the same condition are one row with the latest wording, codes and stage.
 *
 * Not rows: ruled-out conditions; conditions only suspected (working, provisional, "rule out") and never
 * confirmed; diagnoses recorded only to bill an encounter, unless the source says its problem list is built
 * that way.
 *
 * A diagnosis the source attributes to a drug (a named drug, a drug class, or an "adverse effect of <drug>"
 * code) also yields an {@link AllergyIntoleranceRow} for the drug. "Urticaria due to amoxicillin" gives a
 * problem row for urticaria and an allergy row for amoxicillin. A code that names only the adverse effect and
 * no condition (e.g. ICD-10-CM T36.0X5A "adverse effect of penicillins") gives the allergy row alone.
 */
export interface ProblemRow {

  /** The condition in the source's latest wording (e.g. "Moderate persistent asthma"). */
  condition: string;

  /** ICD-10-CM code as the source states it in its latest entry (e.g. "J45.40"). Omit if not given. */
  icd10cm?: string;

  /** SNOMED CT concept id as the source states it in its latest entry. Omit if not given. */
  snomed?: string;

  /** `active`, or `resolved` when the source says resolved, inactive-resolved or historical. */
  status: 'active' | 'resolved';

  /**
   * When the condition began, per the source, as a local date with the source's precision
   * (`{ value: "2019-06", precision: "month" }`). Omit if unknown.
   */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };

  /**
   * Chronic kidney disease rows only: the KDIGO GFR category the source most recently recorded, as recorded
   * by a clinician (from wording, a code, or a category field). Never computed from lab values. Omit otherwise.
   */
  ckd_stage?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';

  /**
   * Chronic kidney disease rows only: the KDIGO albuminuria category the source most recently recorded, as
   * recorded by a clinician (from wording, a code, or a category field). Never computed from lab values.
   * Omit otherwise.
   */
  albuminuria?: 'A1' | 'A2' | 'A3';

  /** Sensitive categories of this condition; see {@link Sensitivity}. Omit when none applies. */
  sensitivity?: Sensitivity[];
  /** Items and entries this row rests on; at least the one giving the latest wording and status. */
  evidence: Evidence;
}

/**
 * A current entry on the list of substances to avoid because of a past reaction. Makes no claim about
 * mechanism. Only current entries: inactive, refuted or entered-in-error entries are not rows, and
 * "no known allergies" is not a row.
 *
 * Also produced from a drug-attributed diagnosis (see {@link ProblemRow}). The substance is then the specific
 * drug when the record names it; when it names only a drug class, the one drug of that class on the patient's
 * medication list in the same item if there is exactly one (class "penicillins", amoxicillin on the list →
 * amoxicillin), otherwise the class as written.
 */
export interface AllergyIntoleranceRow {

  /**
   * For a single drug: generic ingredient name, lower case ("Keflex 500 mg" → "cephalexin"). For anything
   * else (drug classes, combinations, foods, environmental substances): as written ("Sulfonamide
   * antibiotics", "Peanut", "Latex").
   */
  substance: string;

  /** RxNorm ingredient code, only when the source states an ingredient-level code. Never guessed. */
  rxnorm_ingredient?: string;

  /**
   * Decided by what happened, not by which list the source keeps the entry on and not by mechanism.
   * - `hypersensitivity`: hives, rash, swelling of lips/face/tongue, anaphylaxis, bronchospasm, whatever
   *   the mechanism.
   * - `side_effect`: a predictable, non-dangerous effect that made the drug unacceptable (e.g. stomach upset
   *   on erythromycin, drowsiness on an antihistamine).
   * - `serious_adverse_event`: serious harm attributed to the drug that is not a hypersensitivity-type
   *   reaction (e.g. liver injury on isoniazid, pancreatitis on valproate).
   * If the source keeps everything on one undifferentiated list, decide from the recorded reaction.
   */
  reaction_type: 'hypersensitivity' | 'side_effect' | 'serious_adverse_event';

  /**
   * `immune` only when the source (or a confirmed allergy test it records) says the reaction is immune-mediated;
   * `non_immune` when known not to be (well-established non-immune drug effects, e.g. nausea on erythromycin);
   * `unknown` when not established. Use `unknown` when in doubt.
   */
  mechanism: 'immune' | 'non_immune' | 'unknown';

  /** The source's reaction wording, several manifestations joined with "; " (e.g. "hives; lip swelling"). */
  reaction?: string;

  /**
   * `high`: re-exposure could be serious or life-threatening; `low`; `unknown` when the source gives neither.
   * Map a source's severity scale by meaning: mild → low; severe or life-threatening → high.
   */
  criticality: 'low' | 'high' | 'unknown';

  /** When the reaction first occurred, local date with the source's precision. Omit if unknown. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };

  /** Sensitive categories of this entry; see {@link Sensitivity}. Omit when none applies. */
  sensitivity?: Sensitivity[];
  /** Items and entries this row rests on; at least the one giving the current entry. */
  evidence: Evidence;
}

/**
 * Reported analytes and their fixed units (`LabResultRow.unit`). Convert source values to these units.
 *
 * | analyte         | meaning                                      | unit          |
 * |-----------------|----------------------------------------------|---------------|
 * | `creatinine`    | serum/plasma creatinine                      | mg/dL         |
 * | `egfr`          | estimated glomerular filtration rate         | mL/min/1.73m2 |
 * | `potassium`     | potassium                                    | mmol/L        |
 * | `sodium`        | sodium                                       | mmol/L        |
 * | `chloride`      | chloride                                     | mmol/L        |
 * | `bicarbonate`   | bicarbonate (total CO2)                      | mmol/L        |
 * | `anion_gap`     | anion gap                                    | mmol/L        |
 * | `bun`           | urea nitrogen                                | mg/dL         |
 * | `glucose`       | laboratory glucose (not a home meter)        | mg/dL         |
 * | `a1c`           | hemoglobin A1c, NGSP                         | %             |
 * | `uacr`          | urine albumin/creatinine ratio               | mg/g          |
 * | `platelets`     | platelet count                               | 10*3/uL       |
 * | `wbc`           | white blood cell count                       | 10*3/uL       |
 * | `hemoglobin`    | hemoglobin                                   | g/dL          |
 * | `bhb`           | beta-hydroxybutyrate                         | mmol/L        |
 * | `ph`            | pH                                           | [pH]          |
 * | `pco2`          | partial pressure of CO2                      | mmHg          |
 * | `lipase`        | lipase                                       | U/L           |
 * | `troponin`      | troponin I                                   | ng/mL         |
 * | `cholesterol`   | total cholesterol                            | mg/dL         |
 * | `triglycerides` | triglycerides                                | mg/dL         |
 * | `hdl`           | HDL cholesterol                              | mg/dL         |
 * | `ldl`           | LDL cholesterol, measured or calculated      | mg/dL         |
 *
 * 10*3/uL is thousands per microlitre: 350 000 cells/uL is 350. Other analytes are not reported.
 */
export type Analyte =
  | 'creatinine' | 'egfr' | 'potassium' | 'sodium' | 'chloride' | 'bicarbonate' | 'anion_gap' | 'bun'
  | 'glucose' | 'a1c' | 'uacr' | 'platelets' | 'wbc' | 'hemoglobin' | 'bhb' | 'ph' | 'pco2' | 'lipase'
  | 'troponin' | 'cholesterol' | 'triglycerides' | 'hdl' | 'ldl';

/**
 * One laboratory result for a listed analyte ({@link Analyte}).
 *
 * One row per result. A result shown several times (copies in several items, a preliminary then a final copy)
 * is one row, taken from the copy with the most advanced status; its evidence lists the copies used.
 *
 * Only values that stand. Leave out results withdrawn, invalidated or corrected away by the lab; results of
 * orders voided or entered in error; results not performed; superseded copies. A confirmation repeat on a
 * new measurement is a second valid result and its own row.
 *
 * eGFR: one row per calculation the source reports for a specimen. When the source reports variants of one
 * calculation with and without a race coefficient, report only the one without. Report the value as printed;
 * never recompute.
 */
export interface LabResultRow {
  /** Which analyte; see the table on {@link Analyte}. */
  analyte: Analyte;

  /** Numeric value in the analyte's unit, converted if the source used another unit. ">90" → 90. */
  value: number;

  /** The comparator printed with the value (">90" → `>`). Omit for plain values. */
  comparator?: '<' | '>' | '<=' | '>=';

  /** The analyte's fixed unit from the table on {@link Analyte}, written exactly as there (e.g. "mg/dL", "[pH]"). */
  unit: string;

  /**
   * Specimen collection time, RFC 3339 with offset (e.g. `2025-03-04T08:15:00-06:00`). If the source gives a
   * date-time without offset, it is local time: keep the wall-clock time and add the America/Chicago offset in
   * effect then.
   */
  collected: string;

  /** `final` (including amended or corrected values that stand) or `preliminary`. */
  status: 'final' | 'preliminary';

  /**
   * eGFR rows only: the equation the source says it used (CKD-EPI 2021 race-free, CKD-EPI 2009, MDRD);
   * `unknown` if not stated. Omit for other analytes.
   */
  egfr_equation?: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown';

  /** LOINC code of the result as the source gives it. Omit if not given; never looked up. */
  loinc?: string;
  /** Items and entries this row rests on; at least the copy the row's value and status come from. */
  evidence: Evidence;
}

/**
 * A vital-sign set or a home reading.
 *
 * A clinic or hospital vital-sign set (measurements taken within a few minutes at one visit) is one row; a
 * repeat blood pressure later in the same visit goes in `repeat_*`. Each home reading is its own row. Each
 * measurement is reported once: a hand-entered reading that duplicates a device reading taken a minute or two
 * earlier with the same values is one row, preferring the device copy.
 */
export interface VitalRow {

  /** `clinic`; `hospital` (emergency department or inpatient); `home` (patient's own devices). */
  setting: 'clinic' | 'hospital' | 'home';

  /**
   * Local wall-clock time `YYYY-MM-DDTHH:MM` in America/Chicago. For a clinic or hospital set: the time of its
   * first blood pressure, or of its first measurement if it has no blood pressure. For a home reading: the
   * reading's time. Times without offset are already local: report as written.
   */
  local_time: string;
  /** Systolic blood pressure (first reading of the set), mmHg. */
  systolic_mmhg?: number;
  /** Diastolic blood pressure (first reading of the set), mmHg. */
  diastolic_mmhg?: number;

  /** Systolic pressure of a repeat blood pressure later in the same visit, mmHg. Clinic/hospital sets only. */
  repeat_systolic_mmhg?: number;
  /** Diastolic pressure of a repeat blood pressure later in the same visit, mmHg. Clinic/hospital sets only. */
  repeat_diastolic_mmhg?: number;
  /** Pulse (heart rate), beats per minute. */
  pulse_bpm?: number;

  /** Body weight in kg, one decimal (1 lb = 0.45359237 kg; 154 lb → 69.9). */
  weight_kg?: number;

  /**
   * Home glucose reading in mg/dL, whole number (1 mmol/L = 18.016 mg/dL; 5.5 mmol/L → 99). When the meter
   * showed HI or LO, the meter's limit in mg/dL.
   */
  glucose_mg_dl?: number;

  /** `HI` or `LO` when the meter showed that instead of a number; `glucose_mg_dl` is then the meter's limit. */
  glucose_out_of_range?: 'HI' | 'LO';
  /** Items and entries this row rests on. */
  evidence: Evidence;
}
# Write a mapper

You are writing a deterministic mapper from one source system's FOLIO record items into the consumer's app views in `in/views/views.d.ts`.

## What you have (all under `in/`)

- `in/schema/lakeview-v1.d.ts`: the source system's schema. This is the only documentation of the source.
  Its docstrings say what every field and code means; read all of it.
- `in/views/`: the target view definitions, written by the consumer. Their docstrings are the
  specification of the output: which rows to emit, which to leave out, units, statuses, time rules.
- `in/samples/`: 9 sample items from 1 patients of this source, in FOLIO Markdown form
  (frontmatter = envelope, then narrative, then the `json payload` block). `in/samples/samples.json` has
  the same items in JSON form, grouped by patient: that is the form your function receives.
- `in/harness/`: `sh in/harness/check.sh [asOf]` type-checks your mapper (strict, no Node/Bun types) and runs
  it on the sample patients, printing the rows.

## The task

Write `out/transform.ts` exporting

```ts
export function transform(items: FolioItem[], asOf: string): ViewRows
```

(the type `Transform` in `in/views/views.d.ts`). It receives every item this source
published for ONE patient, in no particular order, including items that were later superseded or
retracted, and a local date `asOf` (`YYYY-MM-DD`). It returns the rows describing this source's record
as of the end of that day.

Your mapper will be run, unchanged, on many other patients of this source whose records contain
situations the samples do not show. Rely on the schema's documentation for those, not only on the
samples. Nobody will review the output by hand; a mapper that runs cleanly but reads a field wrongly
produces wrong clinical data.

## Rules

- `out/transform.ts` is self-contained TypeScript. Its only allowed import is
  `import type { … } from "../in/views/views"` (and `"../in/views/views"`). No other imports.
- Deterministic: no clock (`Date.now()`, `new Date()` without an argument), no randomness, no network, no
  file system, no environment. Parsing dates with `Date.parse`/`new Date(string)` and `Intl` time-zone
  formatting are fine.
- It must type-check (`sh in/harness/check.sh`) and must not throw on input it does not expect: skip
  what it cannot read.
- You may write and run your own tests or scratch scripts under `out/` with `bun`. Only
  `out/transform.ts` is used.

